import { appendFile, mkdir, readFile, rename, rm, stat, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { crc32 } from 'node:zlib'
import sharp from 'sharp'
import { canonicalJson, sha256Hex } from '../recipe.ts'
import { runToolChecked, type ToolPaths, toolPaths } from '../tools.ts'

/**
 * Media fixtures for the tests (PLAN 2б, SPEC §12.0 «Тесты», owner 30.10.2026): generated by
 * FFmpeg, sharp and heif-enc — test patterns, tones and noise, no people and no filming.
 * Built once into a cache directory keyed by this file's specs and the tool versions;
 * nothing here is committed.
 */

export const FIXTURE_NAMES = [
  'vfr120',
  'fps120',
  'hdr4k60',
  'vertical',
  'lowrate',
  'av1',
  'bigger',
  'truncated',
  'corrupt',
  'unreadable',
  'editList',
  'apac',
  'apacOnly',
  'adpcm',
  'scenes',
  'heic48mp',
  'rotatedJpeg',
  'smallPng',
] as const
export type FixtureName = (typeof FIXTURE_NAMES)[number]

export interface FixtureSet {
  dir: string
  files: Record<FixtureName, string>
}

const FILE: Record<FixtureName, string> = {
  vfr120: 'vfr120.mov',
  fps120: 'fps120.mp4',
  hdr4k60: 'hdr4k60.mov',
  vertical: 'vertical.mov',
  lowrate: 'lowrate.mp4',
  av1: 'av1.mp4',
  bigger: 'bigger.mov',
  truncated: 'truncated.mp4',
  corrupt: 'corrupt.mov',
  unreadable: 'unreadable.mov',
  editList: 'edit-list.mov',
  apac: 'apac.mov',
  apacOnly: 'apac-only.mov',
  adpcm: 'adpcm.mov',
  scenes: 'scenes.mp4',
  heic48mp: 'heic48mp.heic',
  rotatedJpeg: 'rotated.jpg',
  smallPng: 'small.png',
}

/** Bump with any change below: it re-keys the cache. */
const GENERATOR_VERSION = 5

/** Neutral fixture metadata (no real place: the zero point). */
export const FIXTURE_TAGS = {
  creationTime: '2024-01-02T03:04:05Z',
  make: 'FixtureCam',
  model: 'Pattern 1',
  creationDate: '2024-01-02T06:04:05+0300',
  location: '+00.0000+000.0000/',
} as const

export const FIXTURE_PHOTO_EXIF = {
  make: 'FixtureCam',
  model: 'Pattern 48',
  dateTimeOriginal: '2024:05:06 07:08:09',
  offsetTimeOriginal: '+03:00',
} as const

export async function ensureFixtures(
  options: { dir?: string; paths?: ToolPaths; heifEnc?: string } = {},
): Promise<FixtureSet> {
  const paths = options.paths ?? toolPaths()
  const heifEnc = options.heifEnc ?? process.env.HEIF_ENC_PATH ?? 'heif-enc'
  const base =
    options.dir ?? process.env.CONTENTOPS_FIXTURE_DIR ?? join(tmpdir(), 'contentops-media-fixtures')
  const [ffmpegVersion, heifVersion] = await Promise.all([
    runToolChecked(paths.ffmpeg, ['-hide_banner', '-version'], { captureStdout: true }).then(
      (r) => r.stdout.split('\n')[0] ?? '',
    ),
    runToolChecked(heifEnc, ['--version'], { captureStdout: true }).then((r) => r.stdout.trim()),
  ])
  const key = sha256Hex(
    canonicalJson({
      GENERATOR_VERSION,
      FILE,
      FIXTURE_TAGS,
      FIXTURE_PHOTO_EXIF,
      ffmpegVersion,
      heifVersion,
    }),
  ).slice(0, 12)
  const dir = join(base, key)
  const files = Object.fromEntries(FIXTURE_NAMES.map((n) => [n, join(dir, FILE[n])])) as Record<
    FixtureName,
    string
  >
  if (await exists(join(dir, 'manifest.json'))) return { dir, files }

  const work = join(base, `.tmp-${key}-${process.pid}`)
  await rm(work, { recursive: true, force: true })
  await mkdir(work, { recursive: true })
  const g = new Generator(work, paths, heifEnc)
  try {
    await Promise.all([
      g.vfr120(),
      g.fps120(),
      g.hdr4k60(),
      g.vertical(),
      g.lowrate(),
      g.av1(),
      g.bigger(),
      g.truncated(),
      g.corrupt(),
      g.unreadable(),
      g.editList(),
      g.apac(),
      g.apacOnly(),
      g.adpcm(),
      g.scenes(),
      g.photos(),
    ])
    const manifest: Record<string, string> = {}
    for (const n of FIXTURE_NAMES)
      manifest[FILE[n]] = sha256Hex(await readFile(join(work, FILE[n])))
    await writeFile(join(work, 'manifest.json'), `${JSON.stringify(manifest, null, 2)}\n`)
    await rename(work, dir).catch(async (error) => {
      if (await exists(join(dir, 'manifest.json'))) return
      throw error
    })
  } finally {
    await rm(work, { recursive: true, force: true })
  }
  return { dir, files }
}

async function exists(path: string): Promise<boolean> {
  return stat(path).then(
    () => true,
    () => false,
  )
}

const TONE = (hz: number, sec: number) => [
  '-f',
  'lavfi',
  '-i',
  `sine=frequency=${hz}:sample_rate=48000:duration=${sec}`,
]
const PATTERN = (size: string, fps: number, sec: number) => [
  '-f',
  'lavfi',
  '-i',
  `testsrc2=s=${size}:r=${fps}:d=${sec}`,
]
const NOISE = (size: string, fps: number, sec: number) => [
  '-f',
  'lavfi',
  '-i',
  `nullsrc=s=${size}:r=${fps}:d=${sec},format=yuv420p,geq=lum='random(1)*255':cb=128:cr=128`,
]
const X264 = ['-c:v', 'libx264', '-preset', 'veryfast', '-crf', '18', '-pix_fmt', 'yuv420p']

class Generator {
  readonly dir: string
  readonly paths: ToolPaths
  readonly heifEnc: string
  constructor(dir: string, paths: ToolPaths, heifEnc: string) {
    this.dir = dir
    this.paths = paths
    this.heifEnc = heifEnc
  }

  out(name: FixtureName): string {
    return join(this.dir, FILE[name])
  }

  ff(args: string[]) {
    return runToolChecked(this.paths.ffmpeg, ['-nostdin', '-v', 'error', '-y', ...args])
  }

  /** The benchmark's base case: 120 fps inserts (VFR), two AAC tracks, QuickTime keys. */
  async vfr120() {
    const t = FIXTURE_TAGS
    await this.ff([
      ...PATTERN('320x180', 120, 1),
      ...TONE(997, 1),
      '-map',
      '0:v',
      '-map',
      '1:a',
      '-map',
      '1:a',
      '-vf',
      "select='if(lt(n,60),1,not(mod(n,2)))'",
      '-fps_mode',
      'passthrough',
      ...X264,
      '-c:a',
      'aac',
      '-metadata',
      `creation_time=${t.creationTime}`,
      '-metadata',
      `com.apple.quicktime.make=${t.make}`,
      '-metadata',
      `com.apple.quicktime.model=${t.model}`,
      '-metadata',
      `com.apple.quicktime.creationdate=${t.creationDate}`,
      '-metadata',
      `com.apple.quicktime.location.ISO6709=${t.location}`,
      '-movflags',
      'use_metadata_tags',
      this.out('vfr120'),
    ])
    await padToBitrate(this.out('vfr120'), 1, 16e6)
  }

  async fps120() {
    await this.ff([
      ...PATTERN('640x360', 120, 1),
      ...TONE(440, 1),
      ...X264,
      '-c:a',
      'aac',
      this.out('fps120'),
    ])
    await padToBitrate(this.out('fps120'), 1, 16e6)
  }

  /** 4K 60 fps HEVC 10-bit HLG — skipped as HDR, tone-mapped for previews. */
  async hdr4k60() {
    await this.ff([
      '-f',
      'lavfi',
      '-i',
      'testsrc2=s=3840x2160:r=60:d=1,format=yuv420p10le',
      ...TONE(660, 1),
      '-c:v',
      'libx265',
      '-preset',
      'ultrafast',
      '-x265-params',
      'log-level=error:colorprim=bt2020:transfer=arib-std-b67:colormatrix=bt2020nc',
      '-color_primaries',
      'bt2020',
      '-color_trc',
      'arib-std-b67',
      '-colorspace',
      'bt2020nc',
      '-tag:v',
      'hvc1',
      '-c:a',
      'aac',
      this.out('hdr4k60'),
    ])
  }

  /** Landscape frames with a display matrix: shown portrait, as phones store it. */
  async vertical() {
    const land = join(this.dir, 'vertical-land.mov')
    await this.ff([...PATTERN('1280x720', 30, 1), ...TONE(550, 1), ...X264, '-c:a', 'aac', land])
    await this.ff([
      '-display_rotation:v:0',
      '-90',
      '-i',
      land,
      '-map',
      '0',
      '-c',
      'copy',
      this.out('vertical'),
    ])
    await rm(land)
    await padToBitrate(this.out('vertical'), 1, 16e6)
  }

  /**
   * A cut copy with an edit list: the pre-roll from the keyframe stays in the file as discarded
   * packets (`D`), so `nb_frames` is 60 and a decoder shows 45 — as CapCut exports do.
   */
  async editList() {
    const full = join(this.dir, 'edit-list-full.mov')
    await this.ff([
      ...PATTERN('320x180', 30, 2),
      ...TONE(500, 2),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-b:v',
      '400k',
      '-g',
      '60',
      '-pix_fmt',
      'yuv420p',
      '-c:a',
      'aac',
      full,
    ])
    await this.ff(['-ss', '0.5', '-i', full, '-c', 'copy', this.out('editList')])
  }

  async lowrate() {
    await this.ff([
      ...PATTERN('320x180', 30, 1),
      ...TONE(440, 1),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-b:v',
      '400k',
      '-pix_fmt',
      'yuv420p',
      '-c:a',
      'aac',
      this.out('lowrate'),
    ])
  }

  async av1() {
    await this.ff([
      ...PATTERN('320x180', 30, 1),
      '-c:v',
      'libsvtav1',
      '-preset',
      '12',
      '-crf',
      '40',
      '-svtav1-params',
      'lp=1',
      this.out('av1'),
    ])
  }

  /** Fine texture over the whole frame at a fixed bitrate: CRF 24 needs more bytes. */
  async bigger() {
    await this.ff([
      ...NOISE('640x360', 30, 2),
      ...TONE(440, 2),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-b:v',
      '9M',
      '-maxrate',
      '9M',
      '-bufsize',
      '9M',
      '-pix_fmt',
      'yuv420p',
      '-c:a',
      'aac',
      this.out('bigger'),
    ])
  }

  /** `moov` first, the second half of `mdat` cut off: fewer frames than promised. */
  async truncated() {
    const full = join(this.dir, 'truncated-full.mp4')
    await this.ff([
      ...NOISE('640x360', 30, 2),
      ...TONE(440, 2),
      '-c:v',
      'libx264',
      '-preset',
      'veryfast',
      '-b:v',
      '20M',
      '-pix_fmt',
      'yuv420p',
      '-c:a',
      'aac',
      '-movflags',
      '+faststart',
      full,
    ])
    const bytes = await readFile(full)
    await writeFile(this.out('truncated'), bytes.subarray(0, Math.floor(bytes.length * 0.6)))
    await rm(full)
  }

  /** Damaged bytes inside `mdat`: opens and decodes with errors (not truncated). */
  async corrupt() {
    await this.ff([
      ...PATTERN('640x360', 30, 2),
      ...TONE(440, 2),
      ...X264,
      '-c:a',
      'aac',
      this.out('corrupt'),
    ])
    // Two small damaged spots: decodes with errors and loses at most a couple of frames.
    const bytes = await readFile(this.out('corrupt'))
    for (const at of [0.4, 0.6]) {
      const from = Math.floor(bytes.length * at)
      for (let i = from; i < from + 64; i++) bytes[i] = (bytes[i] as number) ^ 0x5a
    }
    await writeFile(this.out('corrupt'), bytes)
    await padToBitrate(this.out('corrupt'), 2, 16e6)
  }

  async unreadable() {
    await writeFile(this.out('unreadable'), 'not a video\n'.repeat(1000))
  }

  /** AAC plus an `apac`-tagged track (iPhone spatial audio cannot be encoded here). */
  async apac() {
    await this.ff([
      ...PATTERN('320x180', 30, 1),
      ...TONE(440, 1),
      ...TONE(880, 1),
      '-map',
      '0:v',
      '-map',
      '1:a',
      '-map',
      '2:a',
      ...X264,
      '-c:a',
      'aac',
      this.out('apac'),
    ])
    await tagLastTrackApac(this.out('apac'))
    await padToBitrate(this.out('apac'), 1, 16e6)
  }

  async apacOnly() {
    await this.ff([
      ...PATTERN('320x180', 30, 1),
      ...TONE(440, 1),
      ...X264,
      '-c:a',
      'aac',
      this.out('apacOnly'),
    ])
    await tagLastTrackApac(this.out('apacOnly'))
    await padToBitrate(this.out('apacOnly'), 1, 16e6)
  }

  /** IMA ADPCM: MOV carries it, MP4 cannot copy it → the source stays the master. */
  async adpcm() {
    await this.ff([
      ...PATTERN('320x180', 30, 1),
      ...TONE(440, 1),
      ...X264,
      '-c:a',
      'adpcm_ima_qt',
      this.out('adpcm'),
    ])
    await padToBitrate(this.out('adpcm'), 1, 16e6)
  }

  /** 9 s: a pattern, then colour bars from 5 s — a scene change for the annotation frames. */
  async scenes() {
    await this.ff([
      '-f',
      'lavfi',
      '-i',
      'testsrc2=s=320x180:r=30:d=5',
      '-f',
      'lavfi',
      '-i',
      'smptebars=s=320x180:r=30:d=4',
      '-filter_complex',
      '[0:v][1:v]concat=n=2:v=1:a=0[v]',
      '-map',
      '[v]',
      ...X264,
      this.out('scenes'),
    ])
  }

  async photos() {
    const e = FIXTURE_PHOTO_EXIF
    const exif = {
      IFD0: { Make: e.make, Model: e.model },
      IFD2: { DateTimeOriginal: e.dateTimeOriginal, OffsetTimeOriginal: e.offsetTimeOriginal },
    }
    const big = join(this.dir, 'pattern-48mp.png')
    await this.ff(['-f', 'lavfi', '-i', 'testsrc2=s=8064x6048:r=1', '-frames:v', '1', big])
    // Stored landscape, EXIF orientation 6: shown portrait 400×600.
    await sharp(big)
      .resize(600, 400, { fit: 'fill' })
      .jpeg({ quality: 90 })
      .withExif(exif)
      .withMetadata({ orientation: 6 })
      .toFile(this.out('rotatedJpeg'))
    // 48 MP in 512 px tiles, as an iPhone writes it.
    const jpeg = join(this.dir, 'pattern-48mp.jpg')
    await sharp(big).jpeg({ quality: 90 }).withExif(exif).toFile(jpeg)
    await runToolChecked(this.heifEnc, [
      '-q',
      '50',
      '--cut-tiles',
      '512',
      '-p',
      'preset=ultrafast',
      '-o',
      this.out('heic48mp'),
      jpeg,
    ])
    await rm(big)
    await rm(jpeg)
    // Small PNG with a text chunk: no upscaling and chunk stripping.
    const png = await sharp({
      create: { width: 300, height: 200, channels: 3, background: { r: 40, g: 120, b: 200 } },
    })
      .png()
      .toBuffer()
    await writeFile(this.out('smallPng'), withPngText(png, 'Comment', 'fixture text chunk'))
  }
}

/** Appends a `free` box so that size × 8 / duration reaches the bitrate (as the benchmark tests). */
async function padToBitrate(path: string, durationSec: number, bitsPerSecond: number) {
  const size = (await stat(path)).size
  const want = Math.ceil((bitsPerSecond * durationSec) / 8)
  if (size >= want) return
  const extra = Math.max(16, want - size)
  const box = Buffer.alloc(extra)
  box.writeUInt32BE(extra, 0)
  box.write('free', 4, 'latin1')
  await appendFile(path, box)
}

/**
 * Turns the last audio track of a MOV into an `apac` sample entry without a decoder
 * configuration: FFmpeg then sees codec tag `apac`, cannot decode it and MP4 cannot carry
 * it — the behaviour of iPhone spatial audio.
 */
async function tagLastTrackApac(path: string) {
  const bytes = await readFile(path)
  const trak = bytes.lastIndexOf('trak', bytes.length, 'latin1')
  if (trak < 4) throw new Error('no trak box')
  const start = trak - 4
  const end = start + bytes.readUInt32BE(start)
  const region = bytes.subarray(start, end)
  let replaced = 0
  for (const [from, to] of [
    ['mp4a', 'apac'],
    ['esds', 'free'],
  ] as const) {
    let i = region.indexOf(from, 0, 'latin1')
    while (i >= 0) {
      region.write(to, i, 'latin1')
      replaced++
      i = region.indexOf(from, i + 4, 'latin1')
    }
  }
  if (replaced < 2) throw new Error('audio sample entry not found')
  await writeFile(path, bytes)
}

function withPngText(png: Buffer, key: string, text: string): Buffer {
  const data = Buffer.from(`${key}\0${text}`, 'latin1')
  const chunk = Buffer.alloc(12 + data.length)
  chunk.writeUInt32BE(data.length, 0)
  chunk.write('tEXt', 4, 'latin1')
  data.copy(chunk, 8)
  chunk.writeUInt32BE(crc32(chunk.subarray(4, 8 + data.length)), 8 + data.length)
  const ihdrEnd = 8 + 12 + png.readUInt32BE(8)
  return Buffer.concat([png.subarray(0, ihdrEnd), chunk, png.subarray(ihdrEnd)])
}
